<div class="flex justify-between items-center mb-4"><p class="muted text-sm"><?= count($rows) ?> admin users</p><button type="button" class="btn btn-primary" data-modal-template="tpl-add-user" data-modal-title="Add admin user"><?= icon('plus', 'w-4 h-4') ?> Add admin user</button></div>
<div><div class="card overflow-hidden"><div class="overflow-x-auto"><table class="table-x w-full text-sm"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Last login</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($rows as $u): ?><tr><td><b><?= e($u['name']) ?></b></td><td><?= e($u['email']) ?></td><td class="capitalize"><?= e($u['role']) ?></td><td class="text-xs"><?= $u['last_login_at'] ? e(date('d M Y h:i A', strtotime($u['last_login_at']))) : '—' ?></td><td><span class="badge <?= $u['is_active'] ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600' ?>"><?= $u['is_active'] ? 'Active' : 'Disabled' ?></span></td>
<td><?php if ((int)$u['id'] !== (int)$admin['id']): ?><form method="post" action="<?= e(url('/admin/users/' . $u['id'] . '/toggle')) ?>"><?= csrf_field() ?><button class="btn btn-outline btn-sm"><?= $u['is_active'] ? 'Disable' : 'Enable' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<template id="tpl-add-user"><form method="post" action="<?= e(url('/admin/users/save')) ?>" class="space-y-3" data-once><?= csrf_field() ?><input class="input" name="name" placeholder="Full name" required><input class="input" type="email" name="email" placeholder="Email" required><input class="input" type="password" name="password" placeholder="Password (min 10 chars)" minlength="10" required autocomplete="new-password">
<select class="select" name="role"><option value="staff">Staff — orders & enquiries</option><option value="admin">Admin — everything except users</option><option value="superadmin">Super admin — everything</option></select><button class="btn btn-primary w-full">Create user</button></form></template></div>
